// Register six variables on the OPC UA Server:
//   ns=1;s=Line-01.Request   (String, default '')
//   ns=1;s=Line-01.Ack       (String, default '')
//   ns=1;s=Line-02.Request   ...
//   ns=1;s=Line-02.Ack       ...
//   ns=1;s=Line-03.Request   ...
//   ns=1;s=Line-03.Ack       ...
//
// Per node-red-contrib-opcua convention, send one message per variable
// with topic 'ns=1;s=<Name>;datatype=String;browseName=<Name>' and
// payload { opcuaCommand: 'addVariable' }.
//
// addVariable with datatype=String defaults the initial value to ''.
// We deliberately do NOT push an explicit initial-value write here:
// that requires a Variable-write payload shape ({messageType, namespace,
// variableName, variableValue, datatype}) which is easy to get wrong and
// produces noisy warnings. The default is already what we want.

const lines = ['Line-01', 'Line-02', 'Line-03'];
const messages = [];

for (const line of lines) {
    for (const suffix of ['Request', 'Ack']) {
        const varName = `${line}.${suffix}`;
        messages.push({
            topic: `ns=1;s=${varName};datatype=String;browseName=${varName}`,
            payload: { opcuaCommand: 'addVariable' }
        });
    }
}

node.status({ fill: 'green', shape: 'dot', text: `registered ${messages.length} vars` });
return [messages];

// Emit one message per Ack variable to the OpcUa-Client subscribe node.
//   msg.topic   = nodeId (e.g. 'ns=1;s=Line-01.Ack')
//   msg.payload = sampling interval in ms (int)
//
// The client opens a subscription per topic and forwards change
// notifications to its output. (node-red-contrib-opcua convention.)
//
// We use 250 ms sampling; the client time/timeUnit also caps the publish
// rate. Ack writes are very infrequent so this is more than enough.

const interval_ms = 250;
const lines = ['Line-01', 'Line-02', 'Line-03'];
const messages = [];

for (const line of lines) {
    messages.push({
        topic: `ns=1;s=${line}.Ack`,
        payload: interval_ms,
        interval: interval_ms,
        datatype: 'String'
    });
}

node.status({ fill: 'green', shape: 'dot', text: `${messages.length} subs` });
return [messages];

// Input: msg from OPC UA loopback client subscribe.
//   msg.topic   = 'ns=1;s=Line-0X.Ack'
//   msg.payload = new String value (JSON-encoded by line-das)
//
// We skip empty / null payloads (initial server defaults) and JSON-parse
// the rest, then forward a normalised envelope downstream.

const topic = String(msg.topic || '');
const nodeIdMatch = topic.match(/^ns=1;s=(Line-0[123])\.Ack$/);
if (!nodeIdMatch) {
    return null;
}

const payload = msg.payload;
if (payload === '' || payload === undefined || payload === null) {
    return null;  // initial default or empty notification
}

const line = nodeIdMatch[1];

let parsed = null;
let parseError = null;
try {
    parsed = typeof payload === 'string' ? JSON.parse(payload) : payload;
} catch (e) {
    parseError = e.message;
}

const out = {
    topic: `ack/${line}`,
    payload: {
        line,
        raw: payload,
        parsed,
        parseError,
        receivedAt: new Date().toISOString()
    }
};

node.status({ fill: 'blue', shape: 'dot', text: `${line} ack` });
return out;

// Emit a single-line console log for each Ack — visible in `docker logs command-center`.
const p = msg.payload || {};
const rawLen = typeof p.raw === 'string' ? p.raw.length : 0;
const cmd_id = p.parsed && p.parsed.cmd_id;
const result = p.parsed && p.parsed.result;
const accepted = p.parsed && p.parsed.accepted;

const summary = p.parseError
    ? `parseError=${p.parseError} rawLen=${rawLen}`
    : `cmd_id=${cmd_id} accepted=${accepted} result=${result}`;

console.log(`[ACK] line=${p.line} ${summary}`);
return null;

// Useful diagnostic — prints the public endpoint URL clients should use.
const host = 'command-center';
const port = (env.get('OPCUA_SERVER_PORT') || '5160');
const url = `opc.tcp://${host}:${port}/UA/CommandCenter`;
console.log(`[OPC UA Server] endpoint (factory-net): ${url}`);
console.log(`[OPC UA Server] endpoint (host diag)  : opc.tcp://127.0.0.1:${port}/UA/CommandCenter`);
node.status({ fill: 'grey', shape: 'ring', text: url });
return null;

// PR15 Picker — Build pick-and-claim query.
//
// PostgreSQL 제약: SELECT DISTINCT ... FOR UPDATE 는 금지.
// → 2-CTE 로 분리: inner 가 REQUESTED 후보를 FOR UPDATE SKIP LOCKED 로 잠그고,
//   outer 가 그 결과에서 DISTINCT ON (line_id) 로 라인당 1개 추출.
// 라인 in-flight 제약: NOT EXISTS (해당 line_id 의 PICKED/SENT 행).
// claim 은 UPDATE ... SET status='SENT', worker_id, picked_at, started_at = now().
//
// PR16.5: RETURNING 에 retry_epoch (DB now() epoch sec) 추가.
//   fanout 에서 wire payload 에 _retry_epoch 로 머지 → OPC UA Variable 의
//   "같은 값 write 시 변화 감지 안 됨" 이슈를 retry 시 회피.
//   DB schema 는 변경 없음 — extract(epoch from now()) 는 결과셋 계산값일 뿐.

const workerId = env.get('WORKER_ID') || 'command-center';

msg.query = `
WITH locked AS (
    SELECT cr.id, cr.command_id, cr.line_id, cr.request_json,
           cr.priority, cr.created_at
    FROM public.command_request cr
    WHERE cr.status = 'REQUESTED'
      AND NOT EXISTS (
          SELECT 1 FROM public.command_request r2
          WHERE r2.line_id = cr.line_id
            AND r2.status IN ('PICKED', 'SENT')
      )
    ORDER BY cr.line_id, cr.priority ASC, cr.created_at ASC
    FOR UPDATE SKIP LOCKED
),
candidates AS (
    SELECT DISTINCT ON (line_id) id, command_id, line_id, request_json
    FROM locked
    ORDER BY line_id, priority ASC, created_at ASC
)
UPDATE public.command_request t
SET status='SENT', worker_id=$1, picked_at=now(), started_at=now()
FROM candidates c
WHERE t.id = c.id
RETURNING t.id, t.command_id, t.line_id, c.request_json,
          extract(epoch from now())::bigint AS retry_epoch
`;
msg.params = [workerId];
return msg;

// Receives msg.payload = array of rows from RETURNING clause.
//   row.id           bigint
//   row.command_id   int
//   row.line_id      int (1/2/3)
//   row.request_json jsonb (BeApi wire-compatible 4-field object:
//                          {command_id, equipment_id, command_type, value})
//   row.retry_epoch  bigint  (PR16.5 — DB now() epoch sec)
//
// Emits one OPC UA Server write message per row.
//
// Wire payload (stringified JSON in OPC UA String variable):
//   {command_id, equipment_id, command_type, value, _retry_epoch}
//   - 앞 4 필드는 BeApi 와 wire contract (CONTRACT.md §3).
//   - _retry_epoch 는 underscore-prefixed 메타 필드. line-das 측 'decode command
//     json once' 함수가 무시 (메타 필드는 4 필드 contract 와 무관).
//   - 같은 row 가 retry 될 때 _retry_epoch 가 바뀌므로 OPC UA Variable 의
//     deadband / no-change 감지에 걸리지 않고 client subscribe 로 도달.
//
// OpcUa-Server input message shape (variable write):
//   topic   = 'ns=1;s=Line-0X.Request'
//   payload = { messageType: 'Variable', namespace: 1, variableName: 'Line-0X.Request',
//               variableValue: <stringified JSON>, datatype: 'String' }
//   (see X_DAS publish pattern.)

const rows = Array.isArray(msg.payload) ? msg.payload : [];

if (rows.length === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: 'idle' });
    return null;
}

const out = [];
for (const row of rows) {
    const lineId = Number(row.line_id);
    if (![1, 2, 3].includes(lineId)) {
        node.warn(`unexpected line_id=${lineId} on picked row id=${row.id} cmd=${row.command_id}`);
        continue;
    }
    const linePad = `Line-${String(lineId).padStart(2, '0')}`;
    const variableName = `${linePad}.Request`;

    // PR16.5: merge _retry_epoch nonce into wire payload. Keep 4-field
    // contract fields first (BeApi order), then meta key.
    const wirePayload = Object.assign({}, row.request_json || {}, {
        _retry_epoch: Number(row.retry_epoch) || Math.floor(Date.now() / 1000)
    });
    const valueString = JSON.stringify(wirePayload);

    out.push({
        topic: `ns=1;s=${variableName}`,
        payload: {
            messageType: 'Variable',
            namespace: 1,
            variableName,
            variableValue: valueString,
            datatype: 'String'
        },
        _picker_meta: {
            id: row.id,
            command_id: row.command_id,
            line_id: lineId,
            retry_epoch: Number(row.retry_epoch) || null
        }
    });
}

node.status({ fill: 'blue', shape: 'dot', text: `${out.length} picked` });
return [out];

const meta = msg._picker_meta || {};
console.log(`[PICK] line=${meta.line_id} command_id=${meta.command_id} row_id=${meta.id}`);
return null;

// fn_normalize_ack_for_sink
// 입력: ack_router 출력
//   msg.payload = { line, raw, parsed: {line_id, equipment_id, cmd_id, cmd_accepted, cmd_status, observed_at}, parseError, receivedAt }
// 출력: 2개 (latest upsert / event insert) — 두 번째는 fingerprint changed 시에만 emit
// postgresql 노드 호출 패턴: msg.query (string) + msg.params (array)

const p = msg.payload || {};
const parsed = p.parsed || null;
if (!parsed || p.parseError) {
    node.status({ fill: 'yellow', shape: 'ring', text: p.parseError || 'no parsed' });
    return null;
}

const lineId = Number(parsed.line_id);
const equipmentId = Number(parsed.equipment_id);
const commandId = Number(parsed.cmd_id);
const cmdAccepted = Number(parsed.cmd_accepted);
const cmdStatus = Number(parsed.cmd_status);
const accepted = cmdAccepted === 1;

if (!Number.isFinite(lineId) || !Number.isFinite(equipmentId)) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'missing identity' });
    return null;
}
if (!Number.isFinite(commandId) || commandId === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: `${lineId}.${equipmentId} no cmdid` });
    return null;
}
if (!Number.isFinite(cmdStatus)) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'no cmd_status' });
    return null;
}

// status text mapping (init.sql command_latest_response.status 가 text NOT NULL)
function mapStatus(acc, s) {
    if (acc === false) return 'REJECTED';
    if (s === 0) return acc ? 'ACCEPTED' : 'UNKNOWN';
    if (s === 1) return 'RUNNING';
    if (s === 2) return 'COMPLETED';
    if (s === 3) return 'ERROR';
    if (s === 4) return 'FAULT';
    if (s === 5) return 'TIMEOUT';
    if (s === 6) return 'REJECTED_INVALID';
    if (s === 7) return 'REJECTED_BUSY';
    return 'UNKNOWN';
}
const status = mapStatus(accepted, cmdStatus);

const observedAt = parsed.observed_at || p.receivedAt || new Date().toISOString();
const snapshotKey = `${lineId}.${equipmentId}`;
const sourceNodeId = `command-center/ack/${p.line || 'Line-0X'}`;

const responseJson = JSON.stringify({
    source: 'command_center_ack_channel',
    receivedAt: p.receivedAt,
    observed_at: observedAt,
    line: p.line,
    parsed: parsed,
    raw: typeof p.raw === 'string' ? p.raw : JSON.stringify(p.raw)
});

// fingerprint cache for changed detection
const cacheKey = `${lineId}.${equipmentId}`;
const cache = flow.get('cmdSinkFingerprint') || {};
const fingerprint = `${commandId}|${accepted}|${cmdStatus}`;
const prev = cache[cacheKey];
const changed = prev !== fingerprint;
cache[cacheKey] = fingerprint;
flow.set('cmdSinkFingerprint', cache);

// === latest upsert msg ===
const LATEST_SQL = `
INSERT INTO public.command_latest_response (
    line_id, equipment_id, command_id, command_type, status,
    accepted, cmd_status, response_json, source_tsepochms,
    first_observed_at, updated_at, snapshot_key, source_node_id, last_error
) VALUES (
    $1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9,
    COALESCE($10::timestamptz, now()), now(), $11, $12, $13
)
ON CONFLICT (line_id, equipment_id)
DO UPDATE SET
    command_id = EXCLUDED.command_id,
    command_type = EXCLUDED.command_type,
    status = EXCLUDED.status,
    accepted = EXCLUDED.accepted,
    cmd_status = EXCLUDED.cmd_status,
    response_json = EXCLUDED.response_json,
    source_tsepochms = EXCLUDED.source_tsepochms,
    updated_at = now(),
    snapshot_key = EXCLUDED.snapshot_key,
    source_node_id = EXCLUDED.source_node_id,
    last_error = EXCLUDED.last_error
`;

const latestMsg = RED.util.cloneMessage(msg);
latestMsg.topic = 'command.latest.upsert';
latestMsg.query = LATEST_SQL;
latestMsg.params = [
    lineId,
    equipmentId,
    commandId,
    null,
    status,
    accepted,
    cmdStatus,
    responseJson,
    null,
    observedAt,
    snapshotKey,
    sourceNodeId,
    null
];
latestMsg.payload = null;

let eventMsg = null;
if (changed) {
    const EVENT_SQL = `
INSERT INTO public.command_response_event (
    command_id, line_id, equipment_id, accepted, cmd_status, status,
    response_json, source_tsepochms, observed_at, snapshot_key, source_node_id, last_error
) VALUES (
    $1,$2,$3,$4,$5,$6,$7::jsonb,$8,$9::timestamptz,$10,$11,$12
)
`;
    eventMsg = RED.util.cloneMessage(msg);
    eventMsg.topic = 'command.event.insert';
    eventMsg.query = EVENT_SQL;
    eventMsg.params = [
        commandId, lineId, equipmentId, accepted, cmdStatus, status,
        responseJson, null, observedAt, snapshotKey, sourceNodeId, null
    ];
    eventMsg.payload = null;
}

node.status({
    fill: changed ? 'green' : 'blue',
    shape: 'dot',
    text: `${lineId}.${equipmentId} cmd=${commandId} ${changed ? 'latest+event' : 'latest-only'}`
});

return [latestMsg, eventMsg];

// PR17 Ack Handler — Build ack-poll query (idempotent).
//
// Polls CommandDB once per tick. Joins command_request (status='SENT')
// with command_latest_response on (line_id, equipment_id, command_id).
// Picks rows whose cmd_status is terminal (2..7).
//   2 = COMPLETED          → SUCCEEDED
//   3 = BUSY,  4 = FAULT,  5 = TIMEOUT
//   6 = REJECTED_INVALID,  7 = REJECTED_BUSY
//   → all map to FAILED in command_request.status
//
// Idempotency: UPDATE WHERE re-guards t.status='SENT'. Running this
// poll twice in parallel is safe — only one will flip a given row.
//
// Stability under unstable comms: every tick is self-recovering. A missed
// tick or transient DB error simply replays on the next tick because
// command_latest_response is upserted by total-das independently.
//
// retry/timeout 는 PR18 책임. 여기는 terminal ack 만 처리.

msg.query = `
WITH terminal_responses AS (
    SELECT r.id, r.command_id, r.line_id, r.equipment_id, r.worker_id,
           lr.cmd_status, lr.accepted,
           lr.updated_at AS responded_at,
           lr.last_error AS resp_error
    FROM public.command_request r
    JOIN public.command_latest_response lr
      ON lr.line_id = r.line_id
     AND lr.equipment_id = r.equipment_id
     AND lr.command_id = r.command_id
    WHERE r.status = 'SENT'
      AND lr.cmd_status IN (2, 3, 4, 5, 6, 7)
)
UPDATE public.command_request t
SET status = CASE WHEN tr.cmd_status = 2 THEN 'SUCCEEDED' ELSE 'FAILED' END,
    finished_at = COALESCE(tr.responded_at, now()),
    last_error  = CASE WHEN tr.cmd_status = 2 THEN NULL
                       ELSE COALESCE(tr.resp_error,
                                     'cmd_status=' || tr.cmd_status::text)
                  END
FROM terminal_responses tr
WHERE t.id = tr.id
  AND t.status = 'SENT'
RETURNING t.id, t.command_id, t.line_id, t.equipment_id,
          t.status AS new_status, t.finished_at, t.last_error;
`;
msg.params = [];
return msg;

// PR17 Ack Handler — Fan out ack'd rows.
//
// Receives postgresql node result as msg.payload (array of RETURNING rows).
// Splits into per-row messages for console log. No downstream side-effects:
// the UPDATE already terminated the request in the same SQL roundtrip.
//
// Empty array → returns null (silent tick).

const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length) return null;

const out = rows.map(r => ({
    payload: {
        id: r.id,
        command_id: r.command_id,
        line_id: r.line_id,
        equipment_id: r.equipment_id,
        new_status: r.new_status,
        finished_at: r.finished_at,
        last_error: r.last_error
    }
}));
return [out];

// PR17 Ack Handler — console.log for visibility.
// Emits one line to `docker logs command-center` per ack/nack row.
const p = msg.payload || {};
const tag = p.new_status === 'SUCCEEDED' ? 'ACK' : 'NACK';
const err = p.last_error ? ` err=${p.last_error}` : '';
const line = `[${tag}] line=${p.line_id} eq=${p.equipment_id}`
    + ` command_id=${p.command_id} row_id=${p.id}`
    + ` status=${p.new_status}${err}`;
console.log(line);
return null;
